+describe('Store.listShipments on a large dataset', () => {
+  function seeded(count: number): Store {
+    const store = new Store(undefined);
+    for (let i = 0; i < count; i++) {
+      // scrambled creation times, with deliberate ties (i % 1000)
+      const minute = (i * 7919) % 1000;
+      store.addShipment(
+        { ...input(i), carrier: i % 2 ? 'DHL' : 'ATP' },
+        new Date(Date.UTC(2026, 0, 1) + minute * 60_000),
+      );
+    }
+    return store;
+  }
+
+  it('returns the same newest-first result as a full sort, for any limit', () => {
+    const store = seeded(5000);
+    const full = store.listShipments();
+    assert.equal(full.length, 5000);
+    for (let i = 1; i < full.length; i++) assert.ok(full[i - 1].createdAt >= full[i].createdAt);
+    for (const limit of [1, 50, 500, 5000]) {
+      assert.deepEqual(store.listShipments({ limit }), full.slice(0, limit));
+    }
+  });
+
+  it('applies filters before the limit', () => {
+    const store = seeded(5000);
+    const items = store.listShipments({ carrier: 'ATP', limit: 50 });
+    assert.equal(items.length, 50);
+    assert.ok(items.every((s) => s.carrier === 'ATP'));
+    assert.deepEqual(items, store.listShipments({ carrier: 'ATP' }).slice(0, 50));
+  });
+
+  it('is fast enough for the 5k dataset (loose bound, 50 calls)', () => {
+    const store = seeded(5000);
+    const start = performance.now();
+    for (let i = 0; i < 50; i++) store.listShipments({ limit: 50 });
+    assert.ok(performance.now() - start < 1000);
+  });
+});
